	readonly "campaign.invalid_sequence": ErrorDefinition_8gwh4510<"campaign.invalid_sequence">;
	readonly "campaign.invalid_state": ErrorDefinition_8gwh4510<"campaign.invalid_state">;
	readonly "campaign.no_healthy_mailbox": ErrorDefinition_8gwh4510<"campaign.no_healthy_mailbox">;
	readonly "campaign.not_found": ErrorDefinition_8gwh4510<"campaign.not_found">;
	readonly "campaign.not_previewed": ErrorDefinition_8gwh4510<"campaign.not_previewed">;
	readonly "campaign.sequence_version_conflict": ErrorDefinition_8gwh4510<"campaign.sequence_version_conflict">;
	readonly "enrollment.already_active": ErrorDefinition_8gwh4510<"enrollment.already_active">;
	readonly "enrollment.no_consent": ErrorDefinition_8gwh4510<"enrollment.no_consent">;
	readonly "enrollment.not_found": ErrorDefinition_8gwh4510<"enrollment.not_found">;
	readonly "enrollment.suppressed": ErrorDefinition_8gwh4510<"enrollment.suppressed">;
	readonly "play.invalid_state": ErrorDefinition_8gwh4510<"play.invalid_state">;
	readonly "play.no_evidence": ErrorDefinition_8gwh4510<"play.no_evidence">;
	readonly "play.not_found": ErrorDefinition_8gwh4510<"play.not_found">;
