	readonly "mailbox.already_connected": ErrorDefinition_8gwh4521<"mailbox.already_connected">;
	readonly "mailbox.auth_revoked": ErrorDefinition_8gwh4521<"mailbox.auth_revoked">;
	readonly "mailbox.limit_above_ceiling": ErrorDefinition_8gwh4521<"mailbox.limit_above_ceiling">;
	readonly "mailbox.limit_reached": ErrorDefinition_8gwh4521<"mailbox.limit_reached">;
	readonly "mailbox.not_connected": ErrorDefinition_8gwh4521<"mailbox.not_connected">;
	readonly "mailbox.not_found": ErrorDefinition_8gwh4521<"mailbox.not_found">;
	readonly "mailbox.oauth_state_invalid": ErrorDefinition_8gwh4521<"mailbox.oauth_state_invalid">;
	readonly "mailbox.paused": ErrorDefinition_8gwh4521<"mailbox.paused">;
	readonly "send.campaign_not_running": ErrorDefinition_8gwh4521<"send.campaign_not_running">;
	readonly "send.duplicate": ErrorDefinition_8gwh4521<"send.duplicate">;
	readonly "send.no_consent": ErrorDefinition_8gwh4521<"send.no_consent">;
	readonly "send.not_found": ErrorDefinition_8gwh4521<"send.not_found">;
	readonly "send.organization_cap_reached": ErrorDefinition_8gwh4521<"send.organization_cap_reached">;
	readonly "send.outside_window": ErrorDefinition_8gwh4521<"send.outside_window">;
	readonly "send.suppressed": ErrorDefinition_8gwh4521<"send.suppressed">;
	readonly "send.unverified_address": ErrorDefinition_8gwh4521<"send.unverified_address">;
