	readonly "draft.no_prospect_data": ErrorDefinition_8gwh4523<"draft.no_prospect_data">;
	readonly "draft.not_found": ErrorDefinition_8gwh4523<"draft.not_found">;
	readonly "preview.too_many_prospects": ErrorDefinition_8gwh4523<"preview.too_many_prospects">;
	readonly "research.not_found": ErrorDefinition_8gwh4523<"research.not_found">;
